using System.Security.Claims;using EduHub.Api.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace EduHub.Api.Modules.Assignments;
[ApiController,Authorize]
public class AssignmentsController(EduHubDbContext db):ControllerBase{
 int Uid=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 bool IsLecturer=>User.IsInRole("Lecturer");
 async Task<bool> CanAccess(int id)=>User.IsInRole("Admin")||await db.Classes.AnyAsync(x=>x.Id==id&&x.LecturerId==Uid)||await db.ClassMembers.AnyAsync(x=>x.ClassRoomId==id&&x.StudentId==Uid&&x.Status=="Active");
 [HttpGet("api/classes/{classId:int}/assignments")]public async Task<IActionResult> List(int classId){if(!await CanAccess(classId))return Forbid();return Ok(await db.Assignments.Where(x=>x.ClassRoomId==classId).OrderByDescending(x=>x.CreatedAt).ToListAsync());}
 public record CreateRequest(string Title,string Description,DateTime Deadline,bool AllowResubmit=true,int MaxAttempts=2);
 [HttpPost("api/classes/{classId:int}/assignments"),Authorize(Roles="Lecturer")]public async Task<IActionResult> Create(int classId,CreateRequest r){var c=await db.Classes.FindAsync(classId);if(c is null)return NotFound();if(c.LecturerId!=Uid)return Forbid();if(r.Deadline<=DateTime.UtcNow||r.MaxAttempts<1)return BadRequest(new{message="Hạn nộp hoặc số lần nộp không hợp lệ."});var a=new Assignment{ClassRoomId=classId,CreatedById=Uid,Title=r.Title,Description=r.Description,Deadline=r.Deadline,AllowResubmit=r.AllowResubmit,MaxAttempts=r.MaxAttempts};db.Assignments.Add(a);await db.SaveChangesAsync();return Ok(a);}
 public record SubmitRequest(string? Content,string? FileUrl);
 [HttpPost("api/assignments/{id:int}/submissions"),Authorize(Roles="Student")]public async Task<IActionResult> Submit(int id,SubmitRequest r){var a=await db.Assignments.SingleOrDefaultAsync(x=>x.Id==id);if(a is null)return NotFound();if(!await db.ClassMembers.AnyAsync(x=>x.ClassRoomId==a.ClassRoomId&&x.StudentId==Uid&&x.Status=="Active"))return Forbid();if(DateTime.UtcNow>a.Deadline)return BadRequest(new{message="Đã quá hạn nộp bài."});var n=await db.Submissions.CountAsync(x=>x.AssignmentId==id&&x.StudentId==Uid);if((n>0&&!a.AllowResubmit)||n>=a.MaxAttempts)return Conflict(new{message="Không thể nộp thêm bài."});var s=new Submission{AssignmentId=id,StudentId=Uid,AttemptNumber=n+1,Content=r.Content,FileUrl=r.FileUrl};db.Submissions.Add(s);await db.SaveChangesAsync();return Ok(s);}
 [HttpGet("api/assignments/{id:int}/submissions"),Authorize(Roles="Lecturer")]public async Task<IActionResult> Submissions(int id){var a=await db.Assignments.FindAsync(id);if(a is null)return NotFound();if(a.CreatedById!=Uid)return Forbid();return Ok(await db.Submissions.Include(x=>x.Student).Where(x=>x.AssignmentId==id).Select(x=>new{x.Id,x.StudentId,StudentName=x.Student.FullName,x.AttemptNumber,x.Content,x.FileUrl,x.SubmittedAt,x.Score,x.Feedback}).ToListAsync());}
 public record GradeRequest(decimal Score,string? Feedback);
 [HttpPut("api/submissions/{id:int}/grade"),Authorize(Roles="Lecturer")]public async Task<IActionResult> Grade(int id,GradeRequest r){var s=await db.Submissions.Include(x=>x.Assignment).SingleOrDefaultAsync(x=>x.Id==id);if(s is null)return NotFound();if(s.Assignment.CreatedById!=Uid)return Forbid();if(r.Score<0||r.Score>100)return BadRequest(new{message="Điểm phải từ 0 đến 100."});s.Score=r.Score;s.Feedback=r.Feedback;s.GraderId=Uid;s.GradedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(s);}
}